export function resolveSkillCheck(
  seed: number,
  mode: CheckMode,
  modifier: number,
  difficulty: number,
  modeReason: CheckModeReason = 'neutral',
): { seed: number; result: SkillCheckResult } {
  const first = rollOne(seed);
  let finalSeed = first.seed;
  let die = first.die;
  const rolls = [first.die];

  if (mode !== 'normal') {
    const second = rollOne(first.seed);
    finalSeed = second.seed;
    rolls.push(second.die);
    die = mode === 'advantage'
      ? Math.max(first.die, second.die)
      : Math.min(first.die, second.die);
  }

  const safeModifier = Number.isFinite(modifier) ? Math.trunc(modifier) : 0;
  const safeDifficulty = Math.max(1, Math.trunc(Number.isFinite(difficulty) ? difficulty : 10));
  const total = die + safeModifier;

  return {
    seed: finalSeed,
    result: {
      mode,
      modeReason,
      rolls,
      die,
      modifier: safeModifier,
      total,
      difficulty: safeDifficulty,
      outcome: classifyOutcome(die, total, safeDifficulty),
    },
  };
}

export function applyTurnFishingAction(
  session: TurnFishingSession,
  action: TurnFishingAction,
  fish: TurnFishProfile,
  stats: TurnGearStats,
): TurnActionResolution {
  if (session.phase !== 'player-turn' || session.ap <= 0 || session.fishId !== fish.id) {
    return { session, observationSucceeded: false, events: [] };
  }

  let next: TurnFishingSession;
  let observationSucceeded = false;

  if (action === 'release') {
    next = markEvent({
      ...session,
      ap: session.ap - 1,
      tension: clamp(session.tension - (18 + stats.control * 0.7), 0, 120),
      distance: clamp(session.distance + 5 + fish.stats.speed * 0.025, 0, MAX_DISTANCE),
      releasedThisTurn: true,
      lastAction: action,
      lastIntent: session.currentIntent.type,
      lastCheck: null,
      insight: false,
    }, 'action-release');
  } else {
    const result = applyCheckAction(session, action, fish, stats);
    next = { ...result.session, ap: session.ap - 1 };
    observationSucceeded = result.observationSucceeded;
  }

  const settlement = settleAfterPlayerAction(next, fish, stats);
  return {
    session: settlement.session,
    observationSucceeded,
    events: presentationEvents(session, next, settlement.session, action, settlement.fishActionResolved),
  };
}

const kingFishId = kingFishIds.length === 1 ? kingFishIds[0] : undefined;
const kingFish = kingFishId ? fishById.get(kingFishId) : undefined;
const firstKingCatchIndex = events.findIndex((event) => event.trigger === 'king-caught');
if (kingFish && firstKingCatchIndex >= 0 && Array.isArray(kingFish.spotIds)) {
  const kingReachableBeforeDefeat = kingFish.spotIds.some((spotId) => {
    const kingSpot = spotsById.get(spotId);
    if (!kingSpot) return false;
    if (kingSpot.unlockAfter === undefined) return true;
    const gateId = kingSpot.unlockAfter;
    const gate = isNonEmptyString(gateId) ? eventsById.get(gateId) : undefined;
    const gateIndex = isNonEmptyString(gateId) ? eventOrder.get(gateId) : undefined;
    return (gate?.trigger === 'first-catch' || gate?.trigger === 'fish-discovered') &&
      gateIndex !== undefined &&
      gateIndex < firstKingCatchIndex;
  });
  if (!kingReachableBeforeDefeat) {
    errors.push(`King Fish ${kingFishIds[0]} is locked behind an event that cannot occur before the king-caught story event.`);
  }
  if (Array.isArray(kingFish.preferredBaitIds)) {
    for (const baitId of kingFish.preferredBaitIds) {
      const bait = isNonEmptyString(baitId) ? gearById.get(baitId) : undefined;
      const gateId = bait?.unlockAfter;
      const gate = isNonEmptyString(gateId) ? eventsById.get(gateId) : undefined;
      if (gate?.trigger === 'king-caught') {
        errors.push(`King Fish preferred bait "${String(baitId)}" only unlocks after a King Fish is caught.`);
      }
    }
  }
}
